    const grupos = new Map();
    for (const r of results) {
      const li = normLinkedin(r.socialLinks && r.socialLinks.linkedin);
      const emp = norm(r.company && r.company.name);
      const nome = [r.firstName, r.lastName].filter(Boolean).join(' ').trim();
      let motivo = null;
      if (!nome) motivo = 'sem nome';
      else if (lushaIdsExistentes.has(String(r.id))) motivo = 'contato já está no Flow';
      else if (li && linkedinsExistentes.has(li)) motivo = 'LinkedIn já está no Flow';
      else if (emp && empresasExistentes.has(emp) && !grupos.has(emp)) motivo = 'empresa já está no Flow';
      if (motivo) { relatorio.push({ json: { busca: cfg.name, etapa: 'prospecção', pessoa: nome, empresa: r.company && r.company.name, resultado: 'pulado', motivo } }); continue; }
      if (li) linkedinsExistentes.add(li);
      lushaIdsExistentes.add(String(r.id));
      const key = emp || String(r.id);
      if (!grupos.has(key)) grupos.set(key, []);
      grupos.get(key).push(r);
    }

    for (const [key, pessoas] of grupos) {
      const r0 = pessoas[0];
      const empNome = (r0.company && r0.company.name) || 'Empresa sem nome';
      const contatos = pessoas.map((r, i) => ({
        name: [r.firstName, r.lastName].filter(Boolean).join(' ').trim(),
        role: SENIORIDADE_PAPEL[Number(r.jobTitle && r.jobTitle.seniority)] || 'Executivo',
        cargo: (r.jobTitle && r.jobTitle.title) || '',
        email: '', whatsapp: '',
        linkedin: (r.socialLinks && r.socialLinks.linkedin) || '',
        lusha_contact_id: String(r.id),
        is_primary: i === 0
      }));
      const lushaInfo = { busca_id: cfg.id, busca_nome: cfg.name, company_id: r0.company && r0.company.id ? String(r0.company.id) : null, captado_em: new Date().toISOString() };
      try {
        const resp = await flow('POST', '/leads', {
          name: empNome,
          contact_name: contatos[0].name,
          type: 'pj',
          origin: 'Prospecção Lusha',
          stage_name: ETAPA_PROSPECCAO,
          website: (r0.company && r0.company.domain) ? 'https://' + r0.company.domain : null,
          notes: 'Captado pela Lusha (busca: ' + cfg.name + ')' + (contatos[0].cargo ? '\nCargo do contato principal: ' + contatos[0].cargo : ''),
          social_media: { facebook: '', instagram: '', linkedin: '', contacts: contatos, lusha: lushaInfo }
        });
        if (resp && resp.lead) {
          empresasExistentes.add(key);
          fila.push(resp.lead);
          puxados++;
          relatorio.push({ json: { busca: cfg.name, etapa: 'prospecção', empresa: empNome, contato: contatos[0].name, cargo: contatos[0].cargo, pessoas: contatos.length, resultado: 'criado em Prospecção', lead_id: resp.lead.id } });
        }
      } catch (e) {
        relatorio.push({ json: { busca: cfg.name, etapa: 'prospecção', empresa: empNome, resultado: 'ERRO ao criar no Flow', detalhe: String(e.message || e).slice(0, 400) } });
      }
    }
    try { await flow('POST', '/prospecting/lusha-configs/' + cfg.id + '/advance', { page: proxima }); } catch (e) {}
  }

  // ---------- 2) Enriquece até "leads por rodada" empresas da fila ----------
  const lote = fila.slice(0, porRodada);
  const contatosLote = lote.flatMap(c => lerContatos(c.social_media).filter(ct => ct && ct.lusha_contact_id));
  const empresasIds = [...new Set(lote.map(c => c.social_media && c.social_media.lusha && c.social_media.lusha.company_id).filter(Boolean))];

  let saldo = null;
  try { const u = await lusha('GET', '/v3/account/usage'); saldo = Number(u && u.credits && u.credits.remaining); } catch (e) {}
  const custo = contatosLote.length * CUSTO_POR_CONTATO + empresasIds.length * CUSTO_POR_EMPRESA;
  if (Number.isFinite(saldo) && saldo < custo) {
    relatorio.push({ json: { busca: cfg.name, resultado: 'ERRO', motivo: 'saldo de créditos insuficiente para enriquecer', saldo, custo_estimado: custo } });
    continue;
  }

  let enrichC = [], enrichE = [];
  if (contatosLote.length) {
    try { enrichC = (await lusha('POST', '/v3/contacts/enrich', { ids: contatosLote.map(ct => ct.lusha_contact_id), reveal: ['emails', 'phones'] })).results || []; }
    catch (e) { relatorio.push({ json: { busca: cfg.name, resultado: 'ERRO no enrich de contatos', detalhe: String(e.message || e) } }); continue; }
    if (empresasIds.length) {
      try { enrichE = (await lusha('POST', '/v3/companies/enrich', { ids: empresasIds })).results || []; } catch (e) { enrichE = []; }
    }
  }
  const contatoPorId = Object.fromEntries(enrichC.map(x => [String(x.id), x]));
  const empresaPorId = Object.fromEntries(enrichE.map(x => [String(x.id), x]));

  let enriquecidos = 0;
  for (const cli of lote) {
    const sm = cli.social_media || {};
    const info = sm.lusha || {};
    const empresa = empresaPorId[String(info.company_id)] || {};
    const contatos = lerContatos(sm).map(ct => {
      const c = contatoPorId[String(ct.lusha_contact_id)];
      if (!c) return ct;
      return {
        ...ct,
        name: c.fullName || ct.name,
        cargo: (c.jobTitle && c.jobTitle.title) || ct.cargo || '',
        email: pickEmail(c.emails) || ct.email || '',
        whatsapp: normalizePhone(pickPhone(c.phones)) || ct.whatsapp || '',
        linkedin: (c.socialLinks && c.socialLinks.linkedin) || ct.linkedin || ''
      };
    });
    const comContato = contatos.filter(c => c.whatsapp || c.email);

    if (!comContato.length) {
      try {
        await flow('POST', '/leads/' + cli.id + '/stage', { stage_name: 'Lead Perdido', loss_reason: 'Contato inválido', loss_comment: 'Lusha não trouxe telefone nem e-mail' });
        relatorio.push({ json: { busca: cfg.name, etapa: 'enriquecimento', empresa: cli.name, resultado: 'Lead Perdido (Contato inválido)', motivo: 'Lusha não trouxe telefone nem e-mail', lead_id: cli.id } });
      } catch (e) {
        relatorio.push({ json: { busca: cfg.name, etapa: 'enriquecimento', empresa: cli.name, resultado: 'ERRO ao marcar perdido', detalhe: String(e.message || e).slice(0, 300) } });
      }
      continue;
    }

    // Contato principal = quem tem WhatsApp; os sem telefone/e-mail continuam no cadastro
    contatos.forEach(c => { c.is_primary = false; });
    const p = contatos.find(c => c.whatsapp) || comContato[0];
    p.is_primary = true;
    contatos.sort((a, b) => (b.is_primary ? 1 : 0) - (a.is_primary ? 1 : 0));

    const func = empresa.employeeCount ? (empresa.employeeCount.exact || [empresa.employeeCount.min, empresa.employeeCount.max].filter(Boolean).join('-')) : null;
    const notas = [
      'Captado pela Lusha (busca: ' + (info.busca_nome || cfg.name) + ')',
      empresa.industry ? 'Setor: ' + empresa.industry + (empresa.subIndustry ? ' / ' + empresa.subIndustry : '') : null,
      func ? 'Funcionários: ' + func : null,
      p.cargo ? 'Cargo do contato principal: ' + p.cargo : null
    ].filter(Boolean).join('\n');

    try {
      await flow('PATCH', '/leads/' + cli.id, {
        name: empresa.name || cli.name,
        contact_name: p.name,
        email: p.email || null,
        phone: p.whatsapp || null,
        whatsapp: p.whatsapp || null,
        website: empresa.domain ? 'https://' + empresa.domain : (cli.website || null),
        company_description: empresa.description ? String(empresa.description).slice(0, 2000) : null,
        notes: notas,
        social_media: { ...sm, contacts: contatos, lusha: { ...info, enriquecido_em: new Date().toISOString() } }
      });
      await flow('POST', '/leads/' + cli.id + '/stage', { stage_name: ETAPA_ENRIQUECIDO });
      enriquecidos++;
      relatorio.push({ json: { busca: cfg.name, etapa: 'enriquecimento', empresa: empresa.name || cli.name, contato: p.name, cargo: p.cargo, whatsapp: p.whatsapp, email: p.email, resultado: 'enriquecido → ' + ETAPA_ENRIQUECIDO, lead_id: cli.id } });
    } catch (e) {
      relatorio.push({ json: { busca: cfg.name, etapa: 'enriquecimento', empresa: cli.name, resultado: 'ERRO ao atualizar no Flow', detalhe: String(e.message || e).slice(0, 400) } });
    }
  }

  relatorio.push({ json: { busca: cfg.name, resultado: 'resumo da rodada', puxados_para_prospeccao: puxados, pagina_lida, proxima_pagina: proxima, total_na_lusha: total, enriquecidos, ainda_em_prospeccao: Math.max(fila.length - lote.length, 0), saldo_antes_do_enrich: saldo } });
}
return relatorio;
